import fs from 'node:fs';
import vm from 'node:vm';
import { createHash } from 'node:crypto';

// Content-addressed pricing assets avoid stale scripts/styles on the custom domain.
const pricingAssets = Object.fromEntries(['app.js', 'site-config.js', 'styles.css'].map(file => {
  const contents = fs.readFileSync(file);
  const hash = createHash('sha256').update(contents).digest('hex').slice(0, 12);
  const target = `assets/practice-${hash}.${file.endsWith('.css') ? 'css' : 'js'}`;
  fs.writeFileSync(target, contents);
  return [file, '/' + target];
}));

// No dependencies or Cloudflare build step needed: commit the generated HTML.
const elements = new Map();
const context = { window: { IPARKAR_BUILD: true }, document: {
  querySelector: (s) => { if (!elements.has(s)) elements.set(s, {}); return elements.get(s); },
  querySelectorAll: () => [],
}, localStorage: { getItem: () => null } };
vm.createContext(context);
for (const file of ['site-config.js', 'app.js']) vm.runInContext(fs.readFileSync(file, 'utf8'), context);
const S = context.window.SITE, R = context.window.IPARKAR_RENDER;
